                divider = ("v", c)
                break

    if divider is None:
        return grid

    orient, i = divider
    if orient == "h":
        part = grid[:i]
    else:
        part = [row[:i] for row in grid]

    counts = {}
    for row in part:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    noise = min(counts, key=counts.get)

    return [[3 if x == noise else 5 for x in row] for row in part]
