    bottom_colors = {}
    for row in bottom:
        for v in row:
            bottom_colors[v] = bottom_colors.get(v, 0) + 1
    background = max(bottom_colors, key=bottom_colors.get)

    return [[3 if top[r][c] == mark and bottom[r][c] == background else 5
